mapper.delete:
delete f,b,c,d,e from iot_event_source f
    inner join iot_linkage a on f.id=a.event_source_id
    inner join iot_linkage_condition b on a.id=b.linkage_id
    inner join iot_linkage_action c on a.id=c.linkage_id
    inner join iot_linkage_item d on a.id=d.linkage_id
    inner join iot_linkage_condition_item e on e.linkage_condition_id=b.id
where f.id in (

    #{eventSourceId}
);

mapper.select:
select a.*, l.id linkage_id, l.name linkage_name from iot_event_source a
    left join iot_linkage l on a.id=l.event_source_id


        and a.type = #{entity.type}


        and a.device_group_id = #{entity.deviceGroupId}


        and a.name like '%${entity.name}%'

select a.*, esd.model_api_id from iot_event_source a
    left join iot_event_source_detail esd on a.id = esd.event_source_id
where a.id=#{id}
